```javascript
const table = document.querySelector('.table');

table.addEventListener('click', (event) => {
  if (event.target.tagName === 'TH') {
    const header = event.target;
    const column = header.dataset.sort;
    const tbody = table.querySelector('tbody');
    const rows = Array.from(tbody.querySelectorAll('tr'));

    // Get the current sorting order (ascending or descending)
    let sortOrder = 'asc';
    if (header.dataset.order === 'desc') {
      sortOrder = 'desc';
    }

    // Clear existing sort indicators
    const ths = table.querySelectorAll('th');
    ths.forEach(th => th.dataset.order = '');

    // Sort the rows
    rows.sort((a, b) => {
      const valA = a.querySelectorAll('td')[header.cellIndex].textContent.trim();
      const valB = b.querySelectorAll('td')[header.cellIndex].textContent.trim();

      let comparison = 0;
      switch (column) {
        case 'string':
          comparison = valA.localeCompare(valB);
          break;
        case 'number':
          comparison = parseFloat(valA) - parseFloat(valB);
          break;
        case 'date':
          comparison = new Date(valA) - new Date(valB);
          break;
        default:
          comparison = valA.localeCompare(valB); // Default to string
      }

      return sortOrder === 'asc' ? comparison : -comparison;
    });

    // Re-append the sorted rows to the tbody
    tbody.innerHTML = '';
    rows.forEach(row => tbody.appendChild(row));

    // Set the sort order indicator on the header
    header.dataset.order = sortOrder === 'asc' ? 'desc' : 'asc';
  }
});
```

