class FirebaseGuestMiddleware
{
    /**
     * Handle an incoming request.
     *
     * @param  \Illuminate\Http\Request  $request
     * @param  \Closure(\Illuminate\Http\Request): (\Illuminate\Http\Response|\Illuminate\Http\RedirectResponse)  $next
     * @return \Illuminate\Http\Response|\Illuminate\Http\RedirectResponse
     */
    public function handle($request, Closure $next)
    {
        $token = $request->header('Authorization'); // Assuming token is sent in Authorization header

        if (!$token) {
            // Guest user - allow access
            return $next($request);
        }

        try {
            $firebaseAuth = new \Firebase\Auth\FirebaseAuth(config('firebase.credentials_path'));
            $verifiedToken = (new Token())->verifyIDToken($token, config('firebase.api_key'));

            // Store the UID in the session (or request)
            session(['firebase_uid' => $verifiedToken->uid]);

            // Pass the user data to the next middleware/controller
            return $next($request);

        } catch (TokenExpiredException $e) {
            // Token expired - redirect to login
            return redirect('/login');
        } catch (RevokedTokenException $e) {
            // Token revoked - redirect to login
            return redirect('/login');
        } catch (InvalidTokenException $e) {
            // Invalid token - redirect to login
            return redirect('/login');
        } catch (\Exception $e) {
            // Other Firebase errors - log and redirect
            \Log::error('Firebase Authentication Error: ' . $e->getMessage());
            return redirect('/login');
        }
    }
}
