// MARK: - Expression Nodes

/// Represents an expression in the Metal Shading Language.
protocol ExpressionNode: ASTNode {
    /// Type of the expression.
    var type: MetalType { get }
}

// MARK: - Literal Nodes

/// Represents a literal value in the Metal Shading Language.
struct LiteralNode: ExpressionNode {
    let value: Any
    let type: MetalType

    init(_ value: Any, _ type: MetalType) {
        self.value = value
        self.type = type
    }

    var description: String {
        return "Literal(\(value), \(type))"
    }
}

// MARK: - Identifier Nodes

/// Represents an identifier (variable or function name) in the Metal Shading Language.
